# @@ a diagonally dominant system
A = [[10.0, -1.0, 2.0, 0.0], [-1.0, 11.0, -1.0, 3.0], [2.0, -1.0, 10.0, -1.0], [0.0, 3.0, -1.0, 8.0]]
b = [6.0, 25.0, -11.0, 15.0]
# @@ Jacobi iteration: x_new = D^-1 (b - R x)
def jacobi(A: Arr, b: Arr, tol, max_iter) {
    d = diag(A, k=0)
    R = py_bsub(A, diag(d, k=0))
    x = zeros(len(b))
    for k to max_iter {
        x_new = py_bdiv(py_bsub(b, R @ x), d)
        if py_npmax(abs(py_bsub(x_new, x))) < tol {
            return x_new, py_int(k + 1)
        }
        x = x_new
    }
    return x, max_iter
}
# @@ solve and check the residual
TOL = 1e-10
MAX_ITER = 200
x, iters = jacobi(A, b, TOL, MAX_ITER)
print("iterations:", fmt(iters + 0.0, "d"))
print("x =", join(" ", [fmt(py_v3, ".8f") for py_v3 in x]))
print("largest residual", fmt(py_npmax(abs(py_bsub(A @ x, b))), ".1e"))
# @@ checks
if not (py_ballclose(x, [1.0, 2.0, -1.0, 1.0], 1e-05, 1e-09)) {
    stop("AssertionError")
}
